const config = $('Workflow Config').first().json;
const health = $('API Health').first().json;
const tags = $('Ollama Models').first().json;
const openapi = $('API Info').first().json;
const aggregated = $('Aggregate Products').first().json.products ?? [];
const products = aggregated.flatMap(value => Array.isArray(value) ? value : [value]);

if (health.status !== 'ok') {
  throw new Error(`API indisponível: ${JSON.stringify(health)}`);
}

const installedModels = (tags.models ?? []).map(item => item.name ?? item.model);
if (!installedModels.includes(config.model)) {
  throw new Error(`Modelo ${config.model} não está instalado no Ollama`);
}

if (!openapi.paths || Object.keys(openapi.paths).length === 0) {
  throw new Error('O documento OpenAPI não contém paths');
}

if (products.length === 0) {
  throw new Error('A API não retornou produtos para o contexto de execução');
}

return [{
  json: {
    requirement: config.requirement,
    apiBaseUrl: config.apiBaseUrl,
    model: config.model,
    openapi,
    products
  }
}];

