const input = $input.first().json;
let plan = input.output ?? input;
const context = $('Preflight').first().json;
const errors = [];

if (typeof plan === 'string') {
  try { plan = JSON.parse(plan); } catch { plan = null; errors.push('A saída não é JSON válido'); }
}

if (!plan || typeof plan !== 'object') {
  return [{ json: { valid: false, plan, errors: errors.length ? errors : ['Plano ausente'], attempt: 1 } }];
}

for (const field of ['name', 'intent', 'risk', 'oracle', 'steps']) {
  if (plan[field] === undefined || plan[field] === null) errors.push(`Campo obrigatório ausente: ${field}`);
}

if (!Array.isArray(plan.steps) || plan.steps.length < 1 || plan.steps.length > 8) {
  errors.push('steps deve conter entre 1 e 8 passos');
} else {
  const available = new Set();
  const allowedPrefixes = ['/products', '/cart', '/checkout', '/payments', '/orders', '/lab/scenarios'];
  const products = new Map(context.products.map(product => [product.id, product]));
  const isStockRequirement = context.requirement.toLowerCase().includes('estoque');
  let stockGuardStepFound = false;

  for (const [index, step] of plan.steps.entries()) {
    const label = `Passo ${index + 1}`;
    step.method = String(step.method ?? '').toUpperCase();
    const operation = context.openapi.paths?.[step.path]?.[step.method.toLowerCase()];
    const safePath = allowedPrefixes.some(prefix => step.path === prefix || step.path?.startsWith(prefix + '/'));

    if (!['GET', 'POST'].includes(step.method)) errors.push(`${label}: método não permitido: ${step.method}`);
    if (!safePath) errors.push(`${label}: path não permitido: ${step.path}`);
    if (!operation) {
      errors.push(`${label}: ${step.method} ${step.path} não existe no OpenAPI`);
    } else {
      if (!operation.responses?.[String(step.expect_status)]) errors.push(`${label}: status ${step.expect_status} não documentado para ${step.method} ${step.path}`);
      if (operation.requestBody?.required && step.json_body == null) errors.push(`${label}: json_body é obrigatório`);
    }

    const placeholders = [...String(step.path ?? '').matchAll(/\{([^}]+)\}/g)].map(match => match[1]);
    for (const placeholder of placeholders) {
      if (!available.has(placeholder)) errors.push(`${label}: {${placeholder}} foi usado antes de ser criado`);
    }

    if (step.json_body?.product_id && !products.has(step.json_body.product_id)) errors.push(`${label}: produto inexistente: ${step.json_body.product_id}`);

    if (step.method === 'POST' && step.path === '/cart') available.add('cart_id');
    if (step.method === 'POST' && step.path === '/checkout') available.add('order_id');

    if (step.method === 'POST' && step.path === '/cart/{cart_id}/items') {
      stockGuardStepFound = true;
      const product = products.get(step.json_body?.product_id);
      if (isStockRequirement && step.expect_status !== 409) errors.push(`${label}: estoque insuficiente deve esperar HTTP 409`);
      if (isStockRequirement && product && !(step.json_body?.quantity > product.stock)) errors.push(`${label}: quantity deve ser maior que o estoque ${product.stock}`);
    }
  }

  if (isStockRequirement && !stockGuardStepFound) errors.push('O plano não testa POST /cart/{cart_id}/items');
}

return [{ json: { valid: errors.length === 0, plan, errors, attempt: 1 } }];

